const CATEGORIES=['Royalty & Payments','ISBN & Metadata Issues','Printing & Quality','Distribution & Availability','Book Status & Production Updates','General Inquiry'];
const STATUSES=['Open','In Progress','Resolved','Closed'];const PRIORITIES=['Critical','High','Medium','Low'];
const state={token:localStorage.getItem('bl_token'),user:JSON.parse(localStorage.getItem('bl_user')||'null'),page:'home',books:[],tickets:[],authors:[],selected:null,modal:false,filters:{status:'',category:'',priority:''},draft:'',draftSource:'fallback',eventSource:null};
const app=document.getElementById('app');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>n==null?'—':'₹'+Number(n).toLocaleString('en-IN');
const date=d=>d?new Date(d).toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'}):'—';
const initials=s=>String(s||'BL').split(' ').map(x=>x[0]).join('').slice(0,2).toUpperCase();
const BRAND_LOGO='https://static.wixstatic.com/media/6d2cdc_fbad8eb25d304d57be46e9c494a1a355~mv2.jpg/v1/fill/w_180,h_81,al_c,q_80,usm_0.66_1.00_0.01,enc_avif,quality_auto/book%20background%20white.jpg';
const SALES_ICON='https://static.wixstatic.com/media/401514_acfd2d069fae40309e656fad301c464d~mv2.png/v1/fill/w_123,h_110,al_c,q_85,enc_avif,quality_auto/Live%20sales%20report.png';
const ROYALTY_ICON='https://static.wixstatic.com/media/401514_b6a201a9e798431ea8c115447b4219c1~mv2.png/v1/fill/w_105,h_103,al_c,q_85,enc_avif,quality_auto/Highest%20Royalty.png';
const statusClass=s=>({'Open':'open','In Progress':'progress','Resolved':'resolved','Closed':'closed'}[s]||'open');
const priorityClass=s=>(s||'Medium').toLowerCase();
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('show'),2600)}
async function api(url,options={}){const headers={'Content-Type':'application/json',...(options.headers||{})};if(state.token)headers.Authorization='Bearer '+state.token;const res=await fetch(url,{...options,headers});const data=await res.json().catch(()=>({}));if(!res.ok)throw new Error(data.error?.message||'Request failed.');return data}
function persistSession(){if(state.token)localStorage.setItem('bl_token',state.token);else localStorage.removeItem('bl_token');if(state.user)localStorage.setItem('bl_user',JSON.stringify(state.user));else localStorage.removeItem('bl_user')}
function loginView(){app.innerHTML=`<div class="login-wrap"><section class="login-art"><div class="brand"><img class="brand-image" src="${BRAND_LOGO}" alt="BookLeaf Publishing"></div><div><div class="leaf"></div><h1>Every story<br>deserves care.</h1><p>Publishing support that keeps your story moving — from your first draft to the readers who find it.</p></div><div class="art-quote">Thoughtfully published. Personally supported.</div><div class="book-still"><div class="mini">BookLeaf Editions</div><strong>Whispers<br>of the<br>Ganges</strong><span>A STORY BY PRIYA SHARMA</span></div></section><section class="login-side"><form class="login-card" id="loginForm"><div class="eyebrow">AUTHOR & OPERATIONS PORTAL</div><h2>Welcome back</h2><p>Sign in to continue to your BookLeaf workspace.</p><div class="field"><label for="email">Email address</label><input id="email" type="email" autocomplete="username" placeholder="you@example.com" required></div><div class="field"><label for="password">Password</label><input id="password" type="password" autocomplete="current-password" placeholder="Enter your password" required></div><div class="error" id="loginError"></div><button class="btn wide" type="submit">Sign in <span aria-hidden="true">→</span></button><div class="demo-hint"><b>Demo access</b><br>Author: priya.sharma@email.com &nbsp;·&nbsp; bookleaf123<br>Admin: admin@bookleaf.com &nbsp;·&nbsp; admin123</div></form></section></div>`;
 document.getElementById('loginForm').onsubmit=async e=>{e.preventDefault();const error=document.getElementById('loginError');error.textContent='';try{const d=await api('/api/auth/login',{method:'POST',body:JSON.stringify({email:document.getElementById('email').value,password:document.getElementById('password').value})});state.token=d.token;state.user=d.user;persistSession();await boot()}catch(err){error.textContent=err.message}}}
function navItems(){return state.user.role==='admin'?[['queue','◉','Ticket queue'],['books','▤','Book catalog']]:[['home','⌂','Overview'],['books','▤','My books'],['tickets','◷','My tickets']]}
function shell(content){const nav=navItems();app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><img class="brand-image" src="${BRAND_LOGO}" alt="BookLeaf Publishing"></div><div class="workspace-label">${state.user.role==='admin'?'OPERATIONS':'AUTHOR SPACE'}</div><nav class="nav">${nav.map(([id,icon,label])=>`<button data-page="${id}" class="${state.page===id?'active':''}"><span class="nav-icon">${icon}</span>${label}</button>`).join('')}</nav><div class="side-bottom"><div class="user-chip"><span class="avatar">${initials(state.user.name)}</span><div class="user-meta"><b>${esc(state.user.name)}</b><span>${state.user.role==='admin'?'Support team':'BookLeaf author'}</span></div><button class="btn ghost" id="logout" title="Sign out">↗</button></div></div></aside><main class="main"><header class="topbar"><div class="crumb">BookLeaf <span style="padding:0 7px">/</span> <strong>${nav.find(x=>x[0]===state.page)?.[2]||'Overview'}</strong></div><div class="topright"><span><i class="online"></i><span class="online-label">All systems operational</span></span><span class="avatar mobile-name">${initials(state.user.name)}</span></div></header><section class="content">${content}</section></main></div>`;
 app.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{state.page=b.dataset.page;state.selected=null;render()});document.getElementById('logout').onclick=logout;}
async function logout(){try{await api('/api/auth/logout',{method:'POST'})}catch{}state.token=null;state.user=null;persistSession();if(state.eventSource)state.eventSource.close();loginView()}
function render(){if(!state.user){loginView();return}if(state.user.role==='admin'&&state.page==='home')state.page='queue';if(state.user.role==='author'&&state.page==='queue')state.page='home';if(state.page==='home')renderHome();else if(state.page==='books')renderBooks();else if(state.page==='tickets')renderTickets();else renderQueue()}
function stat(label,value,sub,accent=''){return `<div class="stat"><div class="stat-label">${label}<span>${accent||'↗'}</span></div><div class="stat-value">${value}</div><div class="stat-sub">${sub}</div></div>`}
function renderHome(){const total=state.books.length,pending=state.books.reduce((n,b)=>n+(b.royalty_pending||0),0),sold=state.books.reduce((n,b)=>n+(b.total_copies_sold||0),0),active=state.tickets.filter(t=>!['Resolved','Closed'].includes(t.status)).length;const latest=[...state.tickets].sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt)).slice(0,4);shell(`<div class="pagehead"><div><div class="eyebrow">YOUR PUBLISHING DESK</div><h1>Good ${new Date().getHours()<12?'morning':new Date().getHours()<17?'afternoon':'evening'}, ${esc(state.user.name.split(' ')[0])}.</h1><p>A clear view of your books and the people helping you publish.</p></div><button class="btn" id="newTicket">＋ &nbsp;Ask BookLeaf</button></div><div class="stat-grid">${stat('Published titles',total,'Across your BookLeaf catalog','▤')}${stat('Copies sold',sold.toLocaleString('en-IN'),'All-time reported sales',`<img class="stat-art" src="${SALES_ICON}" alt="">`)}${stat('Royalties pending',money(pending),'Across all titles',`<img class="stat-art" src="${ROYALTY_ICON}" alt="">`)}${stat('Open conversations',active,active?'Our team is on it':'You’re all caught up','◷')}</div><div class="card"><div class="card-head"><div><h3>Your books</h3><p>Sales and royalty snapshot</p></div><button class="link-btn" id="seeBooks">View all books →</button></div>${bookTable(state.books.slice(0,5))}</div><div class="card" style="margin-top:17px"><div class="card-head"><div><h3>Recent conversations</h3><p>Updates from your BookLeaf support team</p></div><button class="link-btn" id="seeTickets">View all →</button></div>${latest.length?`<div class="ticket-thread">${latest.map(t=>ticketCard(t)).join('')}</div>`:`<div class="empty">No conversations yet. We’re here when you need us.</div>`}</div>`);document.getElementById('newTicket').onclick=openModal;document.getElementById('seeBooks').onclick=()=>{state.page='books';render()};document.getElementById('seeTickets').onclick=()=>{state.page='tickets';render()};}
function bookTable(books){return books.length?`<div class="table-wrap"><table><thead><tr><th>Title</th><th>ISBN</th><th>Status</th><th>Copies sold</th><th>Earned</th><th>Paid</th><th>Pending</th></tr></thead><tbody>${books.map(b=>`<tr><td><span class="book-title">${esc(b.title)}</span><span class="muted">${esc(b.genre||'')}</span></td><td>${esc(b.isbn)}</td><td><span class="status ${b.status==='Published & Live'?'status-resolved':'status-progress'}">${esc(b.status)}</span></td><td>${Number(b.total_copies_sold||0).toLocaleString('en-IN')}</td><td class="money">${money(b.total_royalty_earned)}</td><td class="money">${money(b.royalty_paid)}</td><td class="money ${b.royalty_pending?'pending':''}">${money(b.royalty_pending)}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">Your book details will appear here.</div>`}
function renderBooks(){const totalPending=state.books.reduce((n,b)=>n+(b.royalty_pending||0),0);shell(`<div class="pagehead"><div><div class="eyebrow">YOUR CATALOG</div><h1>My books</h1><p>Your titles, sales and royalty details in one place.</p></div></div><div class="stat-grid">${stat('All titles',state.books.length,'Published and in production')}${stat('Copies sold',state.books.reduce((n,b)=>n+(b.total_copies_sold||0),0).toLocaleString('en-IN'),'Across your catalog')}${stat('Royalties earned',money(state.books.reduce((n,b)=>n+(b.total_royalty_earned||0),0)),'Total reported')}${stat('Pending royalties',money(totalPending),'Amounts not yet paid')}</div><div class="book-grid">${state.books.map(b=>`<article class="book-card"><div class="book-card-top"><div><h3>${esc(b.title)}</h3><div class="book-sub">${esc(b.isbn)}</div></div><span class="status ${b.status==='Published & Live'?'status-resolved':'status-progress'}">${esc(b.status==='Published & Live'?'Live':'In production')}</span></div><div class="book-gen">${esc(b.genre||'Genre pending')} · Published ${date(b.publication_date)}</div><div class="book-metrics"><div><div class="metric-label">MRP</div><div class="metric-value">${money(b.mrp)}</div></div><div><div class="metric-label">COPIES SOLD</div><div class="metric-value">${Number(b.total_copies_sold||0).toLocaleString('en-IN')}</div></div><div><div class="metric-label">ROYALTY EARNED</div><div class="metric-value">${money(b.total_royalty_earned)}</div></div><div><div class="metric-label">ROYALTY PAID</div><div class="metric-value">${money(b.royalty_paid)}</div></div><div><div class="metric-label">PENDING</div><div class="metric-value pending">${money(b.royalty_pending)}</div></div><div><div class="metric-label">LAST PAYOUT</div><div class="metric-value" style="font-size:11px">${date(b.last_royalty_payout_date)}</div></div></div><div class="book-gen">Print partner: ${esc(b.print_partner||'To be assigned')}</div></article>`).join('')}</div><div class="notice"><span class="notice-icon">i</span><span>Royalties are calculated quarterly and paid within 45 days of the quarter ending. Balances below ₹1,000 roll over to the next quarter. Review your linked bank details in your account settings before the next payout.</span></div>`)}
function ticketCard(t){return `<article class="card thread-card"><div class="thread-card-head"><span class="avatar">${initials(state.user.name)}</span><div class="thread-info"><strong>${esc(state.user.name)}</strong><span>${date(t.createdAt)} · ${esc(t.id)}</span></div><span class="status status-${statusClass(t.status)}">${esc(t.status)}</span></div><h3>${esc(t.subject)}</h3><div class="body">${esc(t.description)}</div><div class="pill-row" style="margin-top:12px"><span class="priority priority-${priorityClass(t.priority)}">${esc(t.priority)} priority</span><span class="category-tag" style="background:#f2f3ef;color:#788079">${esc(t.category)}</span>${t.bookId?`<span class="category-tag" style="background:#f2f3ef;color:#788079">${esc(state.books.find(b=>b.book_id===t.bookId)?.title||t.bookId)}</span>`:''}</div>${t.messages?.length?`<div class="thread-reply"><div class="section-mini">BOOKLEAF SUPPORT · ${date(t.messages.at(-1).at)}</div><div class="body">${esc(t.messages.at(-1).text)}</div><div class="byline" style="margin-top:8px;font-size:10px;color:var(--muted)">— ${esc(t.messages.at(-1).by)}</div></div>`:`<div class="thread-reply"><div class="section-mini">NEXT STEP</div><div class="body">Your request is with our team. We’ll post a response here as soon as we have an update.</div></div>`}</article>`}
function renderTickets(){const sorted=[...state.tickets].sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));shell(`<div class="pagehead"><div><div class="eyebrow">SUPPORT, WITH CONTEXT</div><h1>My conversations</h1><p>Follow every question and response from your BookLeaf team.</p></div><button class="btn" id="newTicket">＋ &nbsp;New conversation</button></div><div class="ticket-thread">${sorted.length?sorted.map(ticketCard).join(''):`<div class="card empty">No tickets yet. Start a conversation and our team will help.</div>`}</div>`);document.getElementById('newTicket').onclick=openModal}
function filteredTickets(){return state.tickets.filter(t=>(!state.filters.status||t.status===state.filters.status)&&(!state.filters.category||t.category===state.filters.category)&&(!state.filters.priority||t.priority===state.filters.priority))}
function renderQueue(){const tickets=filteredTickets();if(!state.selected&&tickets.length)state.selected=tickets[0].id;const selected=tickets.find(t=>t.id===state.selected);const open=state.tickets.filter(t=>!['Resolved','Closed'].includes(t.status)).length,critical=state.tickets.filter(t=>t.priority==='Critical'&&!['Resolved','Closed'].includes(t.status)).length;const authorMap=Object.fromEntries(state.authors.map(a=>[a.id,a]));shell(`<div class="pagehead"><div><div class="eyebrow">BOOKLEAF OPERATIONS</div><h1>Support queue</h1><p>Prioritize the next best action for every author.</p></div><div class="pill-row"><span class="status status-open">${open} active</span>${critical?`<span class="priority priority-critical">${critical} critical</span>`:''}</div></div><div class="stat-grid">${stat('Active tickets',open,'Awaiting resolution')}${stat('Critical priority',critical,'Requires immediate review')}${stat('Resolved',state.tickets.filter(t=>t.status==='Resolved').length,'Across this queue')}${stat('All conversations',state.tickets.length,'Seeded and new tickets')}</div><div class="ticket-layout"><section class="card"><div class="card-head" style="display:block"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px"><div><h3>Inbox</h3><p>${tickets.length} conversations</p></div></div><div class="filters"><select id="filterStatus"><option value="">All statuses</option>${STATUSES.map(x=>`<option ${state.filters.status===x?'selected':''}>${x}</option>`).join('')}</select><select id="filterPriority"><option value="">All priorities</option>${PRIORITIES.map(x=>`<option ${state.filters.priority===x?'selected':''}>${x}</option>`).join('')}</select></div><select id="filterCategory" style="margin-top:8px;width:100%"><option value="">All categories</option>${CATEGORIES.map(x=>`<option ${state.filters.category===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="ticket-list">${tickets.length?tickets.map(t=>`<div class="ticket-item ${state.selected===t.id?'selected':''}" data-ticket="${esc(t.id)}"><div class="ticket-item-top"><span class="priority priority-${priorityClass(t.priority)}">${esc(t.priority)}</span><span class="muted" style="font-size:9px">${esc(t.id)}</span></div><h4>${esc(t.subject)}</h4><p>${esc(t.description)}</p><div class="ticket-item-foot"><span>${esc(authorMap[t.authorId]?.name||'Author')} · ${date(t.createdAt)}</span><span class="status status-${statusClass(t.status)}">${esc(t.status)}</span></div></div>`).join(''):`<div class="empty">No tickets match these filters.</div>`}</div></section><section class="card detail">${selected?detailPanel(selected,authorMap[selected.authorId]):`<div class="detail-empty"><div><i>✧</i>Select a conversation to review the author’s question and prepare a response.</div></div>`}</section></div>`);for(const [id,key] of [['filterStatus','status'],['filterPriority','priority'],['filterCategory','category']])document.getElementById(id).onchange=e=>{state.filters[key]=e.target.value;state.selected=null;renderQueue()};document.querySelectorAll('[data-ticket]').forEach(el=>el.onclick=()=>{state.selected=el.dataset.ticket;state.draft='';renderQueue()});if(selected)bindDetail(selected)}
function detailPanel(t,author){return `<div class="detail-head"><div class="detail-overline"><span>${esc(t.id)} · ${date(t.createdAt)}</span><span class="priority priority-${priorityClass(t.priority)}">${esc(t.priority)} priority</span></div><h2>${esc(t.subject)}</h2><div class="detail-meta">${esc(author?.name||'Author')} · ${esc(author?.email||'')} ${t.bookId?' · '+esc(t.bookId):' · General inquiry'}</div></div><div class="detail-body"><div class="author-line"><span class="avatar">${initials(author?.name)}</span><div><strong>${esc(author?.name)}</strong><span>Author · ${esc(author?.city||'')}</span></div></div><div class="section-mini">AUTHOR QUERY</div><div class="query-box">${esc(t.description)}</div><div class="section-mini">TRIAGE & CLASSIFICATION</div><div class="pill-row"><select id="categorySelect" aria-label="Category">${CATEGORIES.map(c=>`<option ${t.category===c?'selected':''}>${c}</option>`).join('')}</select><select id="prioritySelect" aria-label="Priority">${PRIORITIES.map(p=>`<option ${t.priority===p?'selected':''}>${p}</option>`).join('')}</select><span class="ai-tag">AI CLASSIFIED</span></div>${t.messages?.length?`<div class="section-mini">SENT RESPONSE</div>${t.messages.map(m=>`<div class="reply-box">${esc(m.text)}<div class="byline">${esc(m.by)} · ${date(m.at)}</div></div>`).join('')}`:''}${t.notes?.length?`<div class="section-mini">INTERNAL NOTES</div>${t.notes.map(n=>`<div class="admin-note"><b>${esc(n.by)} · ${date(n.at)}</b><br>${esc(n.text)}</div>`).join('')}`:''}<div class="section-mini">INTERNAL NOTE</div><div class="note-form"><input id="noteInput" placeholder="Add a note for your team…"><button class="btn secondary small" id="addNote">Add note</button></div></div><div class="admin-controls"><select id="statusSelect">${STATUSES.map(s=>`<option ${s===t.status?'selected':''}>${s}</option>`).join('')}</select><button class="btn secondary small" id="assign">${t.assignedTo?'Assigned: '+esc(t.assignedTo):'Assign to me'}</button><span class="spacer"></span><span class="muted" style="font-size:9px">${t.assignedTo?'Owned by '+esc(t.assignedTo):'Unassigned'}</span></div><div class="compose"><div class="compose-top"><b>Reply to author</b><button id="generateDraft" class="btn secondary small">✧ Generate AI draft</button></div><textarea id="draftText" placeholder="Write a thoughtful response. You can generate a draft to get started…">${esc(state.draft)}</textarea><div class="compose-actions"><span id="draftInfo">${state.draftSource==='ai'?'AI-assisted draft · Please review before sending':''}</span><button class="btn small" id="sendReply">Send response →</button></div></div>`}
async function bindDetail(t){document.getElementById('categorySelect').onchange=e=>patch(t,{category:e.target.value});document.getElementById('prioritySelect').onchange=e=>patch(t,{priority:e.target.value});document.getElementById('statusSelect').onchange=e=>patch(t,{status:e.target.value});document.getElementById('assign').onclick=()=>patch(t,{assignedTo:t.assignedTo?'':state.user.name});document.getElementById('draftText').oninput=e=>{state.draft=e.target.value;state.draftSource='manual'};document.getElementById('generateDraft').onclick=async()=>{const btn=document.getElementById('generateDraft');btn.disabled=true;btn.textContent='Drafting…';try{const d=await api(`/api/tickets/${encodeURIComponent(t.id)}/draft`,{method:'POST',body:'{}'});state.draft=d.draft;state.draftSource=d.source;renderQueue();toast(d.source==='ai'?'AI draft ready':'Suggested draft ready — AI is unavailable')}catch(e){toast(e.message);btn.disabled=false;btn.textContent='✧ Generate AI draft'}};document.getElementById('sendReply').onclick=async()=>{const text=document.getElementById('draftText').value.trim();if(!text)return toast('Write or generate a response first.');try{await api(`/api/tickets/${encodeURIComponent(t.id)}/messages`,{method:'POST',body:JSON.stringify({text})});state.draft='';await refresh();toast('Response sent to the author.')}catch(e){toast(e.message)}};document.getElementById('addNote').onclick=async()=>{const input=document.getElementById('noteInput'),text=input.value.trim();if(!text)return;try{await api(`/api/tickets/${encodeURIComponent(t.id)}/notes`,{method:'POST',body:JSON.stringify({text})});await refresh();toast('Internal note added.')}catch(e){toast(e.message)}}}
async function patch(t,body){try{await api(`/api/tickets/${encodeURIComponent(t.id)}`,{method:'PATCH',body:JSON.stringify(body)});await refresh()}catch(e){toast(e.message)}}
function openModal(){state.modal=true;const books=state.books;const modal=document.createElement('div');modal.className='modal-backdrop';modal.id='modalBackdrop';modal.innerHTML=`<div class="modal"><div class="modal-head"><div><div class="eyebrow" style="margin-bottom:5px">AUTHOR SUPPORT</div><h2>Start a conversation</h2></div><button class="btn ghost" id="closeModal">✕</button></div><form id="ticketForm"><div class="modal-body"><div class="field"><label for="ticketBook">What is this about?</label><select id="ticketBook"><option value="">General / Account Level</option>${books.map(b=>`<option value="${esc(b.book_id)}">${esc(b.title)}</option>`).join('')}</select></div><div class="field"><label for="ticketSubject">Subject</label><input id="ticketSubject" maxlength="120" placeholder="A short summary of your question" required></div><div class="field"><label for="ticketDescription">Tell us a little more</label><textarea id="ticketDescription" maxlength="4000" placeholder="Share any details that will help our team look into this…" required></textarea></div><label class="file-label" for="attachment">＋ &nbsp;Attach a file (optional) <input id="attachment" type="file" hidden accept="image/*,.pdf"><span id="fileName"></span><div style="margin-top:5px">Images or PDF · attachment preview only</div></label><div class="error" id="ticketError" style="margin-top:10px"></div><div class="modal-foot"><span style="color:var(--muted);font-size:10px">Our team typically replies within 2 business days.</span><button class="btn" type="submit">Send to BookLeaf →</button></div></div></form></div>`;document.body.appendChild(modal);document.getElementById('closeModal').onclick=closeModal;modal.onclick=e=>{if(e.target===modal)closeModal()};document.getElementById('attachment').onchange=e=>document.getElementById('fileName').textContent=e.target.files[0]?` · ${e.target.files[0].name}`:'';document.getElementById('ticketForm').onsubmit=async e=>{e.preventDefault();const error=document.getElementById('ticketError');error.textContent='';try{await api('/api/tickets',{method:'POST',body:JSON.stringify({bookId:document.getElementById('ticketBook').value||null,subject:document.getElementById('ticketSubject').value,description:document.getElementById('ticketDescription').value})});closeModal();await refresh();state.page='tickets';render();toast('Your message is with the BookLeaf team.')}catch(err){error.textContent=err.message}}}
function closeModal(){document.getElementById('modalBackdrop')?.remove();state.modal=false}
async function refresh(){try{const [tickets,books]=await Promise.all([api('/api/tickets'),api('/api/books')]);state.tickets=tickets.tickets;state.authors=tickets.authors||[];state.books=state.user.role==='admin'?[]:books.books;if(state.user.role==='admin')state.books=[];render()}catch(e){toast(e.message)}}
async function boot(){try{await api('/api/me');const [tickets,books]=await Promise.all([api('/api/tickets'),api('/api/books')]);state.tickets=tickets.tickets;state.authors=tickets.authors||[];state.books=state.user.role==='admin'?[]:books.books;state.page=state.user.role==='admin'?'queue':'home';render();if(state.eventSource)state.eventSource.close();state.eventSource=new EventSource('/api/events?token='+encodeURIComponent(state.token));state.eventSource.addEventListener('ticket',e=>{const t=JSON.parse(e.data);const i=state.tickets.findIndex(x=>x.id===t.id);if(i<0)state.tickets.unshift(t);else state.tickets[i]=t;if(state.user.role==='admin')state.authors=state.authors.length?state.authors:[];const onInput=document.activeElement?.id==='draftText';const cur=state.draft;render();if(onInput){const ta=document.getElementById('draftText');if(ta){ta.focus();ta.value=cur}}});}catch{state.token=null;state.user=null;persistSession();loginView()}}
if(state.token&&state.user)boot();else loginView();
